description:
Implement a `useSwitch` hook that returns `{ isOn, toggle, switchOn, switchOff, label }`. `label` is the string `'On'` when `isOn` is `true` and `'Off'` when `false`.

**Example:**
```tsx
const { isOn, toggle, switchOn, switchOff, label } = useSwitch(false);
// label === 'Off'
```

starter_code:
import { useState } from 'react';

export function useSwitch(initial = false) {
  // your code here
}

test_suite:
test('starts at initial value', () => {
  const { result } = renderHook(() => useSwitch(true));
  expect(result.current.isOn).toBe(true);
});

test('switchOn sets isOn to true', () => {
  const { result } = renderHook(() => useSwitch(false));
  act(() => result.current.switchOn());
  expect(result.current.isOn).toBe(true);
});

test('switchOff sets isOn to false', () => {
  const { result } = renderHook(() => useSwitch(true));
  act(() => result.current.switchOff());
  expect(result.current.isOn).toBe(false);
});

test('label is On when isOn is true', () => {
  const { result } = renderHook(() => useSwitch(true));
  expect(result.current.label).toBe('On');
});

// __hidden__
test('label is Off when isOn is false', () => {
  const { result } = renderHook(() => useSwitch(false));
  expect(result.current.label).toBe('Off');
  act(() => result.current.toggle());
  expect(result.current.label).toBe('On');
});

solution:
import { useState } from 'react';

export function useSwitch(initial = false) {
  const [isOn, setIsOn] = useState(initial);
  return {
    isOn,
    toggle: () => setIsOn(v => !v),
    switchOn: () => setIsOn(true),
    switchOff: () => setIsOn(false),
    label: isOn ? 'On' : 'Off',
  };
}
